// @vitest-environment jsdom
// This file runs only in the exact PR #20/PR #21 source integration lane.
// The JSON is generated by executing the actual Python inspect/project pair,
// not synthesized by TypeScript or a mock controller status list.
import { readFileSync } from 'node:fs'
import { afterEach, expect, it, vi } from 'vitest'
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { MemoryRouter, Route, Routes } from 'react-router-dom'
import { api, type WorkspaceReadiness } from '../src/api'
import { VncPage } from '../src/pages/VncPage'
import { PersistentVncSessions } from '../src/vnc/PersistentVncSessions'
import { VncSessionProvider } from '../src/vnc/VncSessionProvider'

const cases = JSON.parse(readFileSync(
  new URL('./backend-contract.generated.json', import.meta.url), 'utf8',
)) as Record<string, WorkspaceReadiness>
const parts = ['accepted-runtime','desktop-readiness','x11-authorization',
               'rfb-availability','browser-grant'] as const
function check(name: string, condition: (typeof parts)[number]) {
  return cases[name].diagnostics!.checks.find(item => item.condition === condition)!
}
function Fixture() {
  return <MemoryRouter initialEntries={['/vnc/one']}>
    <VncSessionProvider>
      <Routes><Route path="/vnc/:workspaceId" element={<VncPage />} /></Routes>
      <PersistentVncSessions />
    </VncSessionProvider>
  </MemoryRouter>
}
function backend(body: () => WorkspaceReadiness) {
  const fetch = vi.fn(async (url: string) => {
    if (url !== '/api/workspaces/one/readiness/') {
      throw new Error('Unexpected browser API endpoint: ' + url)
    }
    return {ok:true, json: async () => body()} as Response
  })
  vi.stubGlobal('fetch',fetch)
  return fetch
}
afterEach(() => {cleanup(); vi.restoreAllMocks(); vi.unstubAllGlobals()})

it('actual backend status/code shapes preserve iframe, 125% zoom and server grant boundary', async () => {
  const grant = vi.spyOn(api,'vncGrant').mockResolvedValue({
    token:'synthetic-grant', expires_at:'future', novnc_url:'about:blank#original',
  })
  let next = cases.healthy
  const fetch = backend(() => next)
  const view = render(<Fixture/>)
  await waitFor(() => expect(view.container.querySelector('iframe')).not.toBeNull())
  const iframe = view.container.querySelector('iframe')!
  const initialSrc = iframe.getAttribute('src')
  fireEvent.click(screen.getByRole('button',{name:'Zoom in'}))
  fireEvent.click(screen.getByRole('button',{name:'Workspace status'}))
  const panel = await screen.findByLabelText('Workspace diagnostics')
  await waitFor(() => expect(panel.textContent).toContain('browser grant · confirmed'))
  expect(panel.textContent).toContain('rfb availability · confirmed')
  for (const name of ['rfb-failed','runtime-replaced','endpoint-rotated',
                      'stale-probe','controller-offline']) {
    next = cases[name]
    const count = fetch.mock.calls.length
    fireEvent.click(screen.getByRole('button',{name:'Refresh status'}))
    await waitFor(() => expect(fetch.mock.calls.length).toBeGreaterThan(count))
    await waitFor(() => expect(panel.textContent).toContain(
      'rfb availability · ' + check(name,'rfb-availability').status))
    for (const condition of parts) {
      const backendCode = check(name,condition)
      expect(panel.textContent).toContain(backendCode.code)
      expect(panel.textContent).toContain(
        condition.replaceAll('-',' ') + ' · ' + backendCode.status)
    }
    expect(view.container.querySelector('iframe')).toBe(iframe)
    expect(iframe.getAttribute('src')).toBe(initialSrc)
    expect(screen.getByLabelText('Viewer zoom').textContent).toBe('125%')
    expect(grant).toHaveBeenCalledTimes(1)
  }
  expect((screen.getByRole('button',{name:'Connect desktop'}) as HTMLButtonElement).disabled).toBe(true)
  expect(panel.textContent).not.toContain('/private/')
  expect(panel.textContent).not.toContain('synthetic-grant')
})

it('backend runtime replacement invalidates earlier saved grant, not just stage probes', () => {
  expect(check('healthy','browser-grant')).toMatchObject({
    status:'confirmed',code:'grant-record-current',source:'saved-record',
  })
  for (const name of ['runtime-replaced','endpoint-rotated']) {
    expect(cases[name].desktop).toBe('not-verified')
    for (const condition of parts) {
      expect(check(name,condition).status).toBe('unknown')
    }
  }
  expect(check('rfb-failed','x11-authorization').status).toBe('confirmed')
  expect(check('rfb-failed','rfb-availability')).toMatchObject({
    status:'failed', code:'rfb-invalid',
  })
  expect(check('rfb-failed','browser-grant').status).toBe('unknown')
  expect(check('stale-probe','rfb-availability').status).toBe('unknown')
  for (const checkCase of Object.values(cases)) {
    expect(checkCase.read_only).toBe(true)
    expect(checkCase.diagnostics?.advisory).toBe(true)
    expect(checkCase.diagnostics?.checks).toHaveLength(5)
  }
})

it('delayed grant responses cannot bypass the backend outage or reuse a discarded URL', async () => {
  let resolveFirst!: (value: Awaited<ReturnType<typeof api.vncGrant>>) => void
  const grant = vi.spyOn(api,'vncGrant')
    .mockImplementationOnce(() => new Promise(resolve => { resolveFirst = resolve }))
    .mockRejectedValueOnce(new Error('server declined stale request'))
    .mockResolvedValueOnce({token:'new',expires_at:'future',novnc_url:'about:blank#fresh'})
  backend(() => cases['controller-offline'])
  render(<Fixture/>)
  await waitFor(() => expect(grant).toHaveBeenCalledTimes(1))
  fireEvent.click(screen.getByRole('button',{name:'Workspace status'}))
  const panel = await screen.findByLabelText('Workspace diagnostics')
  await waitFor(() => expect(panel.textContent).toContain('controller unavailable'))
  expect((screen.getByRole('button',{name:'Connect desktop'}) as HTMLButtonElement).disabled).toBe(true)
  // Explicitly close a pending viewer, preserving only local view settings.
  fireEvent.click(screen.getByRole('button',{name:'Zoom in'}))
  fireEvent.click(screen.getByRole('button',{name:'Workspace status'}))
  // The status toggle closes the panel, not the pending viewer.
  // Request cancellation through the provider occurs on explicit close
  // after the first authorization response is refused/obsolete.
  resolveFirst({token:'first',expires_at:'past',novnc_url:'about:blank#obsolete'})
  const first = await screen.findByTitle('VNC workspace one')
  fireEvent.click(screen.getByRole('button',{name:'Close viewer'}))
  expect(screen.queryByTitle('VNC workspace one')).toBeNull()
  fireEvent.click(screen.getByRole('button',{name:/^Connect$/}))
  await screen.findByText('server declined stale request')
  expect(screen.queryByTitle('VNC workspace one')).toBeNull()
  fireEvent.click(screen.getByRole('button',{name:/^Connect$/}))
  const current = await screen.findByTitle('VNC workspace one')
  expect(current.getAttribute('src')).toBe('about:blank#fresh')
  expect(screen.getByLabelText('Viewer zoom').textContent).toBe('125%')
  expect(grant).toHaveBeenCalledTimes(3)
})
